    .reg .u64 %rd<40>;
    .reg .u32 %r<80>;
    .reg .f32 %f<10>;
    .reg .pred %p<30>;

    ld.param.u64 %rd1, [input_ptr];
    ld.param.u64 %rd2, [weight_ptr];
    ld.param.u64 %rd3, [bias_ptr];
    ld.param.u64 %rd4, [output_ptr];
    ld.param.u32 %r1, [total_elements];
    ld.param.u32 %r2, [has_bias];

    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;
    cvta.to.global.u64 %rd4, %rd4;

    mov.u32 %r3, %ctaid.x;
    mov.u32 %r4, %ntid.x;
    mov.u32 %r5, %tid.x;
    mad.lo.s32 %r6, %r3, %r4, %r5;   // idx

    setp.ge.s32 %p1, %r6, %r1;
    @%p1 bra DONE;

    // decode idx : dims: W_out=70,H_out=36,D_out=18,OC=16
    div.s32 %r7, %r6, 70;
    rem.s32 %r8, %r6, 70;      // ow

    div.s32 %r9, %r7, 36;
    rem.s32 %r10, %r7, 36;    // oh

    div.s32 %r11, %r9, 18;
    rem.s32 %r12, %r9, 18;    // od

    div.s32 %r13, %r11, 16;
    rem.s32 %r14, %r11, 16;   // oc
    mov.u32 %r15, %r13;       // b

    // output linear offset
    mul.lo.s32 %r16, %r15, 725760;
    mul.lo.s32 %r17, %r14, 45360;
    add.s32  %r16, %r16, %r17;
    mul.lo.s32 %r17, %r12, 2520;
    add.s32  %r16, %r16, %r17;
    mul.lo.s32 %r17, %r10, 70;
    add.s32  %r16, %r16, %r17;
    add.s32  %r16, %r16, %r8;

