    setp.ge.s32 %p2, %r20, 32;
    @%p2 bra IC_DONE;

    mul.lo.s32 %r21, %r20, 32768;
    add.s32  %r21, %r21, %r18;      // input offset (b,ic)

    mul.lo.s32 %r22, %r20, 1680;
    add.s32  %r22, %r22, %r19;      // weight offset (ic,oc)

    mov.u32 %r23, 0;    // kd
KD_LOOP:
    setp.ge.s32 %p3, %r23, 3;
    @%p3 bra KD_DONE;

    sub.s32 %r24, %r12, %r23;      // id = od - kd
    setp.lt.s32 %p4, %r24, 0;
    setp.ge.s32 %p5, %r24, 16;
    or.pred  %p6, %p4, %p5;
