    mul.lo.s32 %r25, %r24, 2048;
    add.s32  %r25, %r25, %r21;

    mul.lo.s32 %r26, %r23, 35;
    add.s32  %r26, %r26, %r22;

    mov.u32 %r27, 0;   // kh
