    setp.ge.s32 %p7, %r27, 5;
    @%p7 bra KH_DONE;

    sub.s32 %r28, %r10, %r27;
    setp.lt.s32 %p8, %r28, 0;
    setp.ge.s32 %p9, %r28, 32;
    or.pred  %p10, %p8, %p9;
    @%p10 bra KH_NEXT;

    mul.lo.s32 %r29, %r28, 64;
    add.s32  %r29, %r29, %r25;

    mul.lo.s32 %r30, %r27, 7;
    add.s32  %r30, %r30, %r26;

    mov.u32 %r31, 0;   // kw
KW_LOOP:
    setp.ge.s32 %p11, %r31, 7;
    @%p11 bra KW_DONE;

