    add.s32 %r31, %r31, 1;
    bra.uni KW_LOOP;
KW_DONE:

KH_NEXT:
    add.s32 %r27, %r27, 1;
    bra.uni KH_LOOP;
KH_DONE:

KD_NEXT:
    add.s32 %r23, %r23, 1;
    bra.uni KD_LOOP;
KD_DONE:

    add.s32 %r20, %r20, 1;
    bra.uni IC_LOOP;
IC_DONE:

    setp.eq.s32 %p15, %r2, 0;
    @%p15 bra STORE;

    mul.wide.s32 %rd14, %r14, 4;
    add.s64  %rd15, %rd3, %rd14;
    ld.global.f32 %f4, [%rd15];
    add.f32 %f1, %f1, %f4;

STORE:
    mul.wide.s32 %rd16, %r16, 4;
    add.s64  %rd17, %rd4, %rd16;
    st.global.f32 [%rd17], %f1;

